entries[464638] = { ["name"] = "Schäumendes Toxin", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin zähflüssiger Schaum bedeckt 9 Sek. lang den Spielercharakter und detoniert anschließend, was 978574 Naturschaden verursacht. Dieser Effekt ist stapelbar.\n\nJeder Spielercharakter innerhalb von 8 Metern um die Explosion von ' Reaktiver Schaum ' verringert die Stapel des Gebrechens.\n\nWenn der Effekt abläuft, wird das Opfer mit entsprechend vielen Stapeln ' Siechendes Gift ' belegt." }
