entries[464754] = { ["name"] = "Geschwader - Inaktiv", ["text"] = "Ihr fliegt allein.\n\nIhr startet kein Segelgeschwader und tretet auch keinem bei.\n\nDiese Option ist kostenlos." }
entries[464755] = { ["name"] = "Geschwader - Aktiviert", ["text"] = "Ihr könnt Segelgeschwader starten oder ihnen beitreten.\n\nNach dem Einsatz von 'Segeln' können bis zu zwei weitere Dracthyr, die sich in Eurer Gruppe und Nähe befinden, automatisch teilnehmen und an Eurer Seite segeln.\n\nBei Bewegung, Zauber oder Verwickelung in einen Kampf verlasst Ihr diese Aktivität.\n\nDiese Option ist kostenlos." }
entries[464756] = { ["name"] = "Zerschmetterte Essenz", ["text"] = "200 Meter Reichweite\nSofort\nUmgeben von der Essenz des zerschmetterten Kristalls, die eintreffenden Schaden um 0% verringert. Dieser Effekt ist stapelbar." }
entries[464757] = { ["name"] = "Unheilvolles Gebrüll", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 2 sek. Abklingzeit\nEine schreckliche Kakophonie verringert die Bewegungsgeschwindigkeit aller Gegner innerhalb von 30 Metern 15 Sek. lang um 50%." }
