entries[464769] = { ["name"] = "Zorn der Feuerlande", ["text"] = "200 Meter Reichweite\nWirken in 12 sek.\nEin brennender Geist opfert sich, um Botschafter Flammenschlag mit feuriger Kraft zu erfüllen, sodass er allen Spielercharakteren alle 2 Sek. 644 Feuerschaden zufügt, bis alle Stapel verbraucht wurden." }
entries[464771] = { ["name"] = "Portalanker beschwören", ["text"] = "200 Meter Reichweite\nSofort\nFlammenschlag öffnet Portale in die Feuerlande. Brennende Geister strömen alle 15 Sek. aus den Feuerlanden heraus, bis zwei Portalanker in der Nähe zerstört werden." }
entries[464772] = { ["name"] = "Belohnung: Schock und Flamme", ["text"] = "Wirken in 3 sek.\nDas Einwerfen einer Schockmarke und einer Flammenmarke führt dazu, dass eine überhitzte Spule entsteht. Diese elektrische Spule setzt ' Siechflammen ' frei, wenn sie erschaffen oder aktiviert wird." }
