entries[464776] = { ["name"] = "Betrug entdeckt!", ["text"] = "Wirken in 3 sek.\nDer einarmige Bandit schummelt erfolgreich, wenn nicht genug Marken eingeworfen werden oder eine zuvor ausgewählte Walzenkombination eingerastet ist, wodurch sich der verursachte Schaden dauerhaft um 500% erhöht." }
