entries[464801] = { ["name"] = "Belohnung: Schock und Bombe", ["text"] = "Wirken in 3 sek.\nDas Einwerfen einer Schockmarke und einer Bombenmarke führt dazu, dass eine dynamitbeladene Spule entsteht. Diese elektrische Spule setzt Dynamitbeute frei, wenn sie erschaffen oder aktiviert wird." }
entries[464802] = { ["name"] = "Relikt von Uldum", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrann schwingt ein mächtiges uraltes Relikt, das heilige Energie ausstrahlt und Verbündete 20 Sek. lang alle 1 Sek. um eine erhebliche Menge Gesundheit heilt." }
entries[464804] = { ["name"] = "Belohnung: Flamme und Bombe", ["text"] = "Wirken in 3 sek.\nDas Einwerfen einer Flammenmarke und einer Bombenmarke sorgt dafür, dass mehrere feurige Dynamitbeutebots herbeigerufen werden, deren Gesundheit um 100% erhöht und Bewegungsgeschwindigkeit um 30% verringert ist. Sie detonieren mit ' Brennschlag '." }
entries[464806] = { ["name"] = "Belohnung: Flamme und Münze", ["text"] = "Wirken in 3 sek.\nDas Einwerfen einer Flammenmarke und einer Münzmarke führt dazu, dass der einarmige Bandit 8 Sek. lang alle 0.5 Sek. glühend heiße Münzen auf alle Spielercharaktere verschießt. Diese Münzen verursachen 6 Sek. lang alle 0.5 Sek. 251553 Feuerschaden. Dieser Effekt ist stapelbar." }
