entries[464883] = { ["name"] = "Legionshieb", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nBenötigt Waffen\nEin starker Angriff, der allen Gegnern vor der Teufelswache [0.816 * (Zaubermacht * 0.5) * 1 * (1 + Vielseitigkeit)] Schaden zufügt. Außerdem wird die Effektivität jeglicher erhaltenen Heilung des Opfers 12 Sek. lang um 20% verringert.\n\n(Mit Rechtsklick umschalten)" }
entries[464884] = { ["name"] = "Lebende Bombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas Ziel wird zu einer lebenden Bombe, erleidet im Verlauf von 2 Sek. 4 Feuerschaden und explodiert dann, wodurch es sich selbst zusätzlich (26.8% der Zaubermacht) Feuerschaden sowie allen anderen Gegnern innerhalb von 10 Metern verringerten Schaden zufügt.\n\nGegner, die von der Explosion getroffen wurden, werden ebenfalls zu lebenden Bomben, dieser Effekt kann sich aber nicht weiter ausbreiten." }
