entries[464886] = { ["name"] = "Neuralvergrößerer", ["text"] = "Sofort\nVerstärkt zeitweise Eure Spürwerkzeuge, wodurch die Sichtbarkeit des Götzen von Ohn'ahra und der aufgerüsteten Denkkappe deutlich erhöht wird." }
