entries[464888] = { ["name"] = "Lichtbrechender Strahl", ["text"] = "Unbegrenzte Reichweite\nSofort\nI.N.G.A. schleudert einen feurigen Energiestrahl auf bis zu 5 Spielercharaktere und fügt Spielercharakteren im Effektbereich 2909339 Feuerschaden zu.\n\nInstabile Stacheln, die von diesem Effekt getroffen werden, werden zerstört." }
