entries[464890] = { ["name"] = "Hand von Gul'dan", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört einen dämonischen Meteor voller Wildwichtel herab, die hervorbrechen, um das Ziel anzugreifen.\n\nFügt beim Einschlag allen Gegnern innerhalb von 8 Metern um das Ziel bis zu [3 * (55.6876% der Zaubermacht)] Schattenflammenschaden zu [ Hand der Verdammnis : belegt alle getroffenen Ziele mit 'Verdammnis' ] und beschwört, basierend auf den aufgezehrten Seelensplittern, bis zu 3 Wildwichtel." }
