entries[465022] = { ["name"] = "Schutz der Ahnen", ["text"] = "Sofort\nBeschwört für 30 Sek. ein Totem am Zielort. Alle Verbündeten innerhalb von [ Totemische Konzentration : 23 / 20] Metern um das Totem erhalten um 10% erhöhte Gesundheit. Wenn ein Verbündeter stirbt, wird das Totem aufgezehrt und gestattet ihm die Reinkarnation mit 20% Gesundheit und Mana.\n\nKann keinen Verbündeten reinkarnieren, der an massivem Schaden gestorben ist." }
