entries[466002] = { ["name"] = "Violett gepanzerter Knurrer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Smaks weiß die ein oder andere Sache über das Halten von Hyänen. Erste Regel: Finger weg von den Zähnen!\"\nVerkäufer:\nSmaks Oberskimmer\nZone:\nLorenhall\nKosten:\n8.125" }
