entries[466007] = { ["name"] = "Bombenhülse", ["text"] = "Sofort\nKriecherbomben haben zum Schutz eine robuste Bombenhülle, die sämtlichen eingehenden Schaden um 99% verringert.\n\nSie explodieren nur bei Kontakt mit ihrem Ziel und fügen Spielercharakteren innerhalb von 5 Metern 300 Feuerschaden zu." }
entries[466011] = { ["name"] = "Leuchtendo der Lodernde", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der VIP unter den VIPs des Garbagio zu sein, hat seine Vorteile, darunter die Schlüssel zum ehemaligen Metzelmeister. Durch hochmoderne Goblintechnologie schafft er ganze 30 Meter auf den Liter!\"\nVerkäufer:\nAndo die Knarre\nZone:\nBefreiung von Lorenhall\nKosten:\n777" }
entries[466012] = { ["name"] = "Donnertrommelfehlzündung", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Wurde nach einem besonders grausigen Aufeinandertreffen von der Tribüne des Kessels geborgen. Auf die Frage, ob es sich um einen Blindgänger handelt, antwortete Torqs Management mit: \"Vermutlich?\"\"\nHändler:\nAndo die Knarre\nZone:\nBefreiung von Lorenhall\nKosten:\n500" }
entries[466013] = { ["name"] = "Ockerfarbene Zustellungsrakete", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Bringt Pakete und Passagiere von A nach B. Und zwar mir Stil!\"\nVerkäufer:\nSchredd der Verschrotter\nZone:\nLorenhall\nKosten:\n11.375" }
entries[466014] = { ["name"] = "Liefermodul des Dampfdruckkartells", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Liefert Euch einen kurzen Trip oder Euren Gegnern eine gewaltige Explosion!\"\nBeute von:\nSchatz des Dampfdruckkartells\nZone:\nLorenhall" }
entries[466016] = { ["name"] = "Oberskimmer Spezial", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Smaks ist sich sicher, dass die Rakete mitten im Flug nicht explodieren wird. Absolut. Total. Zu 100% sicher.\"\nVerkäufer:\nSmaks Oberskimmer\nZone:\nLorenhall\nKosten:\n11.375" }
entries[466017] = { ["name"] = "Innovationsermittler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Wenn der beste Weg zu einer guten Idee wirklich schnell ist.\"\nVerkäufer:\nSkedgit Glutfransen\nZone:\nLorenhall\nKosten:\n25" }
entries[466018] = { ["name"] = "Verwüster der Düsternisverschmolzenen", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Exzellent, wenn es darum geht, eine Riesensauerei zu hinterlassen. Weniger gut darin, sie wieder zu beseitigen.\"\nVerkäufer:\nLage Fiesmöpp\nZone:\nLorenhall\nKosten:\n11.375" }
entries[466019] = { ["name"] = "Schwarzmeerschredder Deluxe Mk. 2", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Man sollte lieber nicht hinterfragen, was mit Mk. 1 passiert ist.\"\nVerkäuferin:\nBootsmann HartiZone:\nLorenhallKosten:\n8.125" }
entries[466020] = { ["name"] = "Personalisierter Goblinverschrotter", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Goblinschredder haben immer wieder bewiesen, in vielen verschiedenen Anwendungen nützlich zu sein, wie beim Holzfällen und Transport. Dieses Modell wurde für den Einsatz mit S.C.H.R.O.T.T. umfunktioniert.\"\nBeute:\nDurchwühlter Schrotthaufen\nZone:\nLorenhall" }
entries[466021] = { ["name"] = "Violetter Goblinschredder", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Schredder wurde liebevoll mit einer rostabweisenden Farbe lackiert, um bleibenden Glanz zu gewährleisten.\"\nBeute von:\nVersand & Logistik\nZone:\nLorenhall" }
entries[466022] = { ["name"] = "Ko-ordinator der Venture Company", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Gebaut, um jegliche Unterfangen der Venture Company an vorderster Front zu unterstützen.\"\nBeute von:\nSchatz der Venture Co.\nZone:\nLorenhall" }
entries[466023] = { ["name"] = "Anlagenbefürworter", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Versichert anderen, dass Eure Anlagen genau da sind, wo sie sein sollten.\"\nVerkäufer:\nSkedgit GlutfransenZone:\nLorenhallKosten:\n25" }
entries[466024] = { ["name"] = "Bombardierer des Bilgewasserkartells", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Für den schnellen Transport von Handelsgütern des Kartells und anderen höchst instabilen Substanzen.\"\nBeute von:\nSchatz des Bilgewasserkartells\nZone:\nLorenhall" }
entries[466025] = { ["name"] = "Margenmanipulator", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Stellt sicher, dass es immer einen marginalen Abstand zwischen Euch und dem absoluten Tiefpunkt gibt.\"\nVerkäufer:\nSkedgit Glutfransen\nZone:\nLorenhall\nKosten:\n25" }
entries[466026] = { ["name"] = "Geborgene Flugmaschine des Goblingeldsacks", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Flugmaschine, einst geschätzter Besitz der Goblineliten, wurde leider dem Schrotthaufen überlassen, nachdem etwas auf dem Markt erschien, das größer, auffälliger und explosiver war.\"\nBeute:\nMüll des Garbagio\nZone:\nLorenhall" }
entries[466027] = { ["name"] = "Spionagedrohne der Düsternisverschmolzenen", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Perfekt für alle, die die Karriereleiter erklimmen wollen, indem sie alles zu IHRER Angelegenheit machen.\"\nWeltquest:\nFällmittel der Düsternisverschmolzenen\nZone:\nLorenhall" }
entries[466028] = { ["name"] = "Supergrüne Flugmaschine", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die besten Ingenieure des Dampfdruckkartells behaupten, dass sie diese mechanische Wunderleistung entwickelt haben, während die anderen Kartelle lediglich ihre Pläne kopiert haben.\"\nVerkäuferin:\n2294/SOURCETEXT\nZone:\nLorenhall\nKosten:\n11.375" }
entries[466029] = { ["name"] = "Bedrohlicher böser Batzen Bomben", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix ruft Sprengstoff herbei, der (größtenteils) kurz darauf detoniert, 12600019 Feuerschaden verursacht und ' Explosionsverbrennung ' auslöst.\n\nEinige Geschosse mitsamt ihrer Zünder verteilen sich jedoch über die Arena." }
